esponse Code\", triggeredtype.text_ as \"Approved/Declined\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->>''pos_entry_mode'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->>''pos_entry_mode'' END  as \"POS Entry Mode\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) =''array'' then cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payee''->>''mcc'' else cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''payee''->>''mcc'' END  as \"Merchant Category Code (MCC)\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''payeeVPA''->>''vpaName'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''observations''->''payeeVPA''->>''vpaName'' END as \"Merchant Name\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' END as \"Merchant Location\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' ELSE cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' END as \"Card Acceptor Country Code\", null as \"Acquirer Country Code\", CASE WHEN jsonb_typeof(cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)) = ''array'' THEN cast(convert_from(Txnorg.bytes_, ''UTF8'') as jsonb)->0->''t